mapper.select:
SELECT tdm02_hr_record_id AS hr_record_id , tdm02_reg_date AS reg_date , ( CASE WHEN tdm02_reg_type = 'NEW' THEN '신규' WHEN tdm02_reg_type = 'UPD' THEN '변동' WHEN tdm02_reg_type = 'DEL' THEN '제거' ELSE '' END ) AS reg_type_nm , tdm02_person_nm AS person_nm , tdm02_change_data AS change_data , tdm02_apply_cd AS apply_code , tdm02_note AS note , tdm02_upd_nm AS upd_nm , COALESCE(TO_CHAR(tdm02_upd_date, 'yyyy-mm-dd HH24:MI:SS'), ''::text) AS upd_date_str FROM tdm02_hr_record WHERE tdm02_company_id = #{companyId} AND COALESCE(tdm02_apply_cd, '0') LIKE #{applyCode} AND CONCAT(tdm02_hr_record, tdm02_person_nm, tdm02_note) ILIKE #{searchText}
AND tdm02_reg_date BETWEEN #{startDate} AND #{closeDate}
ORDER BY tdm02_hr_record_id DESC
LIMIT #{limit}

SELECT tdm02_company_id
  FROM tdm02_hr_record
 WHERE tdm02_hr_record_id = #{hrRecordId}

mapper.update:
UPDATE tdm02_hr_record
   SET tdm02_apply_cd = #{applyCode}
     , tdm02_note     = #{note}
     , tdm02_upd_nm   = #{updName}
     , tdm02_upd_date = f_sysdate()
 WHERE tdm02_hr_record_id = #{hrRecordId}
